package main

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"strings"
	"sync/atomic"
	"time"
)

var (
	errStreamEnded   = errors.New("SSE stream ended")
	errStreamTimeout = errors.New("SSE stream timeout")
)

type gatewayStatus struct {
	Health struct {
		Code int `json:"code"`
	} `json:"health"`
	Activity struct {
		Active       bool   `json:"active"`
		PollSequence uint64 `json:"poll_sequence"`
	} `json:"activity"`
}

func consumeSSE(ctx context.Context, client *http.Client, endpoint, token string, timeout time.Duration, onStatus func(statusInput)) error {
	streamCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	request, err := http.NewRequestWithContext(streamCtx, http.MethodGet, endpoint, nil)
	if err != nil {
		return fmt.Errorf("create SSE request: %w", err)
	}
	request.Header.Set("Accept", "text/event-stream")
	request.Header.Set("Authorization", "Bearer "+token)

	response, err := client.Do(request)
	if err != nil {
		return fmt.Errorf("connect SSE stream: %w", err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK {
		_, _ = io.CopyN(io.Discard, response.Body, 4096)
		return fmt.Errorf("SSE endpoint returned %s", response.Status)
	}
	mediaType, _, err := mime.ParseMediaType(response.Header.Get("Content-Type"))
	if err != nil || mediaType != "text/event-stream" {
		return fmt.Errorf("SSE endpoint returned content type %q", response.Header.Get("Content-Type"))
	}

	activity := make(chan struct{}, 1)
	done := make(chan struct{})
	var timedOut atomic.Bool
	go func() {
		timer := time.NewTimer(timeout)
		defer timer.Stop()
		for {
			select {
			case <-done:
				return
			case <-activity:
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				timer.Reset(timeout)
			case <-timer.C:
				timedOut.Store(true)
				cancel()
				return
			}
		}
	}()
	defer close(done)

	scanner := bufio.NewScanner(response.Body)
	scanner.Buffer(make([]byte, 4096), 64*1024)
	var eventType string
	var data strings.Builder
	var lastPollSequence uint64
	var havePollSequence bool
	dispatch := func() error {
		defer func() {
			eventType = ""
			data.Reset()
		}()
		if eventType != "status" {
			return nil
		}
		var status gatewayStatus
		if err := json.Unmarshal([]byte(data.String()), &status); err != nil {
			return fmt.Errorf("decode SSE status: %w", err)
		}
		if status.Health.Code < 0 || status.Health.Code > 2 {
			return fmt.Errorf("invalid gateway health code %d", status.Health.Code)
		}
		input := statusInput{connected: true, healthCode: status.Health.Code, active: status.Activity.Active}
		if havePollSequence && status.Activity.PollSequence != lastPollSequence && !input.active {
			pulse := input
			pulse.active = true
			onStatus(pulse)
		}
		lastPollSequence = status.Activity.PollSequence
		havePollSequence = true
		onStatus(input)
		return nil
	}

	for scanner.Scan() {
		select {
		case activity <- struct{}{}:
		default:
		}
		line := scanner.Text()
		if line == "" {
			if err := dispatch(); err != nil {
				return err
			}
			continue
		}
		if strings.HasPrefix(line, ":") {
			continue
		}
		field, value, found := strings.Cut(line, ":")
		if !found {
			value = ""
		} else if strings.HasPrefix(value, " ") {
			value = value[1:]
		}
		switch field {
		case "event":
			eventType = value
		case "data":
			separator := 0
			if data.Len() > 0 {
				separator = 1
			}
			if data.Len()+separator+len(value) > 64*1024 {
				return fmt.Errorf("SSE status frame exceeds 64 KiB")
			}
			if separator == 1 {
				data.WriteByte('\n')
			}
			data.WriteString(value)
		}
	}
	if timedOut.Load() {
		return errStreamTimeout
	}
	if err := scanner.Err(); err != nil {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		return fmt.Errorf("read SSE stream: %w", err)
	}
	return errStreamEnded
}
